import React from "react";
import { Link } from "react-router-dom";

export default function OptionsPage() {
  return (
    <>
      <style>{`
        * {
          font-family: 'Lucida Sans', 'Lucida Sans Regular', 'Lucida Grande', 'Lucida Sans Unicode', Geneva, Verdana, sans-serif;
        }
        .mainbox {
          width: 80%;
          max-width: 500px;
          height: auto;
          border-radius: 3%;
          background-color: #fcf9f9;
          margin: 0 auto;
          padding: 20px;
        }
        html, body {
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          background-color: #efefef;
        }
        .image img {
          margin-top: 30px;
          width: 100%;
          max-width: 200px;
        }
        button {
          height: 40px;
          width: 100%;
          font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
          border: none;
          background-color: red;
          color: aliceblue;
          border-radius: 5%;
          margin-bottom: 10px;
        }
        button:hover {
          background-color: black;
          box-shadow: 0 0 5px black;
        }
      `}</style>
      <center>
        <div className="mainbox">
          <div className="image">
            <img
              src="https://login.testpad.chitkara.edu.in/images/chitkara_logo_primary.png"
              alt="Chitkara Logo"
            />
          </div>{" "}
          <br />
          <div className="login">
            <h3> Complaint Box</h3>
            <br />
          </div>

          <Link to="/hostelcomplaint">
            <button>Hostel related Complaint</button>
          </Link>

          <Link to="/messcomplaint">
            <button>Mess related complaint</button>
          </Link>

          <Link to="/campuscomplaint">
            <button>Campus related complaint</button>
          </Link>

          <Link to="/sq1complaint">
            <button>Square 1 related complaint</button>
          </Link>

          <Link to="/other">
            <button>Other</button>
          </Link>
          <br />
          <br />
          <br />

          <Link to="/complaintHistory">
            <button id="history">Complaint history</button>
          </Link>

          <p>*Check your complaints here</p>
        </div>
      </center>
    </>
  );
}
